dslRule:
void setColor(org.eclipse.swt.widgets.Control $control, org.eclipse.swt.graphics.Color $foreground, org.eclipse.swt.graphics.Color $background)
=> void setColors(org.eclipse.swt.widgets.Control $control, org.eclipse.swt.graphics.Color $foreground, org.eclipse.swt.graphics.Color $background)
;;

beforeExample:
import org.eclipse.swt.widgets.Control;
import org.eclipse.swt.graphics.Color;
import org.eclipse.swt.widgets.Display;
import org.eclipse.swt.widgets.Shell;

public class MyInformationControl {
    private Shell fShell;
    private static void setColor(Control control, Color foreground, Color background) {
        control.setForeground(foreground);
        control.setBackground(background);
    }
    public MyInformationControl(Shell parentShell) {
        fShell = new Shell(parentShell);
        Display display = fShell.getDisplay();
        Color foreground = display.getSystemColor(0);
        Color background = display.getSystemColor(1);
        setColor(fShell, foreground, background);
    }
}

afterExample:
import org.eclipse.swt.widgets.Control;
import org.eclipse.swt.graphics.Color;
import org.eclipse.swt.widgets.Display;
import org.eclipse.swt.widgets.Shell;

public class MyInformationControl {
    private Shell fShell;
    private static void setColors(Control control, Color foreground, Color background) {
        control.setForeground(foreground);
        control.setBackground(background);
    }
    public MyInformationControl(Shell parentShell) {
        fShell = new Shell(parentShell);
        Display display = fShell.getDisplay();
        Color foreground = display.getSystemColor(0);
        Color background = display.getSystemColor(1);
        setColors(fShell, foreground, background);
    }
}

